186: void
187: gp_get_usertime(long *pdt)
188: {
189: #if use_times_for_usertime
190:     struct tms tms;
191:     long ticks;
192:     const long ticks_per_sec = CLK_TCK;
193: 
194:     times(&tms);
195:     ticks = tms.tms_utime + tms.tms_stime + tms.tms_cutime + tms.tms_cstime;
196:     pdt[0] = ticks / ticks_per_sec;
197:     pdt[1] = (ticks % ticks_per_sec) * (1000000000 / ticks_per_sec);
198: #else
199:     gp_get_realtime(pdt);       /* Use an approximation on other hosts.  */
